import React, { useState } from 'react';
import { useClipboard } from '../contexts/ClipboardContext';
import { PlusIcon, TrashIcon, ShareIcon, PencilIcon } from '@heroicons/react/24/outline';

const Dashboard = () => {
  const { clipboards, loading, error, createClipboard, updateClipboard, deleteClipboard } = useClipboard();
  const [isCreating, setIsCreating] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    content: '',
    isPrivate: true
  });

  const handleChange = (e) => {
    const value = e.target.type === 'checkbox' ? e.target.checked : e.target.value;
    setFormData({
      ...formData,
      [e.target.name]: value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      if (editingId) {
        await updateClipboard(editingId, formData);
        setEditingId(null);
      } else {
        await createClipboard(formData);
      }
      setFormData({ title: '', content: '', isPrivate: true });
      setIsCreating(false);
    } catch (err) {
      console.error('Failed to save clipboard:', err);
    }
  };

  const handleEdit = (clipboard) => {
    setFormData({
      title: clipboard.title,
      content: clipboard.content,
      isPrivate: clipboard.isPrivate
    });
    setEditingId(clipboard._id);
    setIsCreating(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this clipboard?')) {
      try {
        await deleteClipboard(id);
      } catch (err) {
        console.error('Failed to delete clipboard:', err);
      }
    }
  };

  const handleCopy = async (content) => {
    try {
      await navigator.clipboard.writeText(content);
      alert('Copied to clipboard!');
    } catch (err) {
      console.error('Failed to copy:', err);
      alert('Failed to copy to clipboard');
    }
  };

  const handleShare = (clipboard) => {
    if (clipboard.shareableLink) {
      const shareUrl = `${window.location.origin}/shared/${clipboard.shareableLink}`;
      navigator.clipboard.writeText(shareUrl);
      alert('Share link copied to clipboard!');
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary-500"></div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-900">My Clipboards</h1>
        <button
          onClick={() => {
            setIsCreating(!isCreating);
            setEditingId(null);
            setFormData({ title: '', content: '', isPrivate: true });
          }}
          className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
        >
          <PlusIcon className="-ml-1 mr-2 h-5 w-5" />
          New Clipboard
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-400 text-red-700 px-4 py-3 rounded relative mb-4" role="alert">
          <span className="block sm:inline">{error}</span>
        </div>
      )}

      {isCreating && (
        <form onSubmit={handleSubmit} className="bg-white shadow-sm rounded-lg p-6 mb-6">
          <div className="space-y-4">
            <div>
              <label htmlFor="title" className="block text-sm font-medium text-gray-700">
                Title
              </label>
              <input
                type="text"
                name="title"
                id="title"
                required
                value={formData.title}
                onChange={handleChange}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
              />
            </div>
            <div>
              <label htmlFor="content" className="block text-sm font-medium text-gray-700">
                Content
              </label>
              <textarea
                name="content"
                id="content"
                required
                rows={4}
                value={formData.content}
                onChange={handleChange}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-primary-500 focus:ring-primary-500 sm:text-sm"
              />
            </div>
            <div className="flex items-center">
              <input
                type="checkbox"
                name="isPrivate"
                id="isPrivate"
                checked={formData.isPrivate}
                onChange={handleChange}
                className="h-4 w-4 text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
              />
              <label htmlFor="isPrivate" className="ml-2 block text-sm text-gray-900">
                Private
              </label>
            </div>
            <div className="flex justify-end space-x-3">
              <button
                type="button"
                onClick={() => {
                  setIsCreating(false);
                  setEditingId(null);
                  setFormData({ title: '', content: '', isPrivate: true });
                }}
                className="px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-primary-600 hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500"
              >
                {editingId ? 'Update' : 'Create'}
              </button>
            </div>
          </div>
        </form>
      )}

      <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
        {clipboards.map((clipboard) => (
          <div key={clipboard._id} className="bg-white overflow-hidden shadow-sm rounded-lg">
            <div className="p-6">
              <div className="flex justify-between items-start">
                <h3 className="text-lg font-medium text-gray-900">{clipboard.title}</h3>
                <div className="flex space-x-2">
                  {!clipboard.isPrivate && (
                    <button
                      onClick={() => handleShare(clipboard)}
                      className="p-1 rounded-full text-gray-400 hover:text-gray-500 focus:outline-none"
                    >
                      <ShareIcon className="h-5 w-5" />
                    </button>
                  )}
                  <button
                    onClick={() => handleEdit(clipboard)}
                    className="p-1 rounded-full text-gray-400 hover:text-gray-500 focus:outline-none"
                  >
                    <PencilIcon className="h-5 w-5" />
                  </button>
                  <button
                    onClick={() => handleDelete(clipboard._id)}
                    className="p-1 rounded-full text-gray-400 hover:text-gray-500 focus:outline-none"
                  >
                    <TrashIcon className="h-5 w-5" />
                  </button>
                </div>
              </div>
              <div className="mt-2">
                <p className="text-sm text-gray-500 break-words">{clipboard.content}</p>
              </div>
              <div className="mt-4 flex justify-between items-center">
                <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${
                  clipboard.isPrivate ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'
                }`}>
                  {clipboard.isPrivate ? 'Private' : 'Public'}
                </span>
                <button
                  onClick={() => handleCopy(clipboard.content)}
                  className="text-sm text-primary-600 hover:text-primary-500"
                >
                  Copy
                </button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Dashboard;
